import random
import math
from fractions import Fraction

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_xor_and_network(n, m):
        network = []
        for _ in range(m):
            row = [random.choice([0, 1]) for _ in range(n)]
            network.append(row)
        return network

    def compute_geometric_invariant(network):
        n = len(network[0])
        A = [[0] * (2 * n) for _ in range(2 * n)]

        for i in range(n):
            A[i][i + n] = 1

        for row in network:
            for j in range(n):
                if row[j] == 1:
                    for k in range(n):
                        A[n + j][n + k] += A[k][j]

        rank = 0
        for i in range(2 * n):
            pivot = None
            for j in range(i, 2 * n):
                if A[j][i] != 0:
                    pivot = j
                    break
            if pivot is None:
                continue
            rank += 1
            for j in range(2 * n):
                A[i][j], A[pivot][j] = A[pivot][j], A[i][j]
            for j in range(2 * n):
                if j != i and A[j][i] != 0:
                    factor = Fraction(A[j][i], A[i][i])
                    for k in range(2 * n):
                        A[j][k] -= factor * A[i][k]

        return rank

    def mean(lst):
        return sum(lst) / len(lst)

    def std(lst, m):
        return math.sqrt(sum((x - m) ** 2 for x in lst) / len(lst))

    n_values = [5, 10, 15, 20, 30, 40]
    ranks = []

    for n in n_values:
        for _ in range(5):  # Ensure at least 30 instances per seed
            network = generate_xor_and_network(n, random.randint(1, n))
            rank = compute_geometric_invariant(network)
            ranks.append(rank)

    mean_rank = mean(ranks)
    std_rank = std(ranks, mean_rank)

    return {
        "metric_name": "Minimal Rank of Geometric Invariant",
        "metric_value": mean_rank,
        "instances_tested": len(ranks),
        "conjecture_holds": abs(mean_rank - (n_values[0] ** (2/3))) <= 3 and std_rank < 1,  # Adjust threshold as needed
